const dialogForm = (title, content, okLabel = "Continue", {
  width = 540,
  render,
  disableOk = false,
  classes = ["amw-fc-dialog"],
} = {}) => new Promise((resolve) => {
  let settled = false;
  const finish = (value) => {
    if (settled) return;
    settled = true;
    resolve(value);
  };
  new Dialog({
    title,
    content,
    buttons: {
      ok: {
        icon: '<i class="fas fa-check"></i>',
        label: okLabel,
        callback: (html) => {
          const app = html?.[0]?.closest?.(".app") ?? html?.closest?.(".app");
          const okBtn = app?.querySelector?.('button[data-button="ok"]');
          if (okBtn?.disabled) return finish(null);
          finish(html[0].querySelector("form"));
        },
      },
      cancel: {
        icon: '<i class="fas fa-times"></i>',
        label: "Cancel",
        callback: () => finish(null),
      },
    },
    default: "ok",
    close: () => finish(null),
    render: (html) => {
      const root = html instanceof jQuery ? html[0] : html;
      const app = root?.closest?.(".app");
      const okBtn = app?.querySelector?.('button[data-button="ok"]');
      if (okBtn) {
        okBtn.disabled = Boolean(disableOk);
        okBtn.classList.toggle("disabled", Boolean(disableOk));
      }
      if (typeof render === "function") render(html, { okBtn, app, root });
    },
  }, { width, classes }).render(true);
});

const currencyToCopper = (currency = {}) => {
  const pp = Number(currency.pp) || 0;
  const gp = Number(currency.gp) || 0;
  const ep = Number(currency.ep) || 0;
  const sp = Number(currency.sp) || 0;
  const cp = Number(currency.cp) || 0;
  return (pp * 1000) + (gp * 100) + (ep * 50) + (sp * 10) + cp;
};

const copperToCurrency = (totalCp) => {
  let n = Math.max(0, Math.floor(Number(totalCp) || 0));
  const pp = Math.floor(n / 1000);
  n %= 1000;
  const gp = Math.floor(n / 100);
  n %= 100;
  const ep = Math.floor(n / 50);
  n %= 50;
  const sp = Math.floor(n / 10);
  n %= 10;
  return { pp, gp, ep, sp, cp: n };
};

const formatGpAmount = (gp) => {
  const n = Number(gp) || 0;
  return Number.isInteger(n) ? String(n) : n.toFixed(2);
};

const trySpendGold = async (payer, gpAmount) => {
  const needCp = Math.round(gpAmount * 100);
  const current = foundry.utils.deepClone(payer.system?.currency ?? {});
  const totalCp = currencyToCopper(current);
  if (totalCp < needCp) {
    return { ok: false, haveGp: totalCp / 100 };
  }

  const next = foundry.utils.deepClone(current);
  const haveGp = Number(next.gp) || 0;
  if (haveGp >= gpAmount) {
    next.gp = haveGp - gpAmount;
  } else {
    Object.assign(next, copperToCurrency(totalCp - needCp));
  }

  await payer.update({ "system.currency": next });
  return { ok: true, haveGp: totalCp / 100 };
};

const tryCreditCook = async (cook, gpAmount) => {
  try {
    if (!(cook.isOwner || game.user.isGM)) return false;
    const current = foundry.utils.deepClone(cook.system?.currency ?? {});
    current.gp = (Number(current.gp) || 0) + gpAmount;
    await cook.update({ "system.currency": current });
    return true;
  } catch (_err) {
    return false;
  }
};

const getMealTemplates = (cookActor) => cookActor.items.filter((i) => {
  const cooking = foundry.utils.getProperty(i, "flags.world.cooking") ?? {};
  return Number(cooking.rank) === 1 && Boolean(cooking.mealKey);
}).sort((a, b) => a.name.localeCompare(b.name));

const getDailyTemplates = (cookActor) => {
  const map = new Map();
  for (const i of cookActor.items) {
    const cooking = foundry.utils.getProperty(i, "flags.world.cooking") ?? {};
    if (cooking.dailySkill && Number.isFinite(Number(cooking.index))) {
      map.set(Number(cooking.index), i);
    }
  }
  return map;
};

const getMealBoonHtml = (meal) => {
  const chat = String(meal?.system?.description?.chat ?? "").trim();
  const value = String(meal?.system?.description?.value ?? "").trim();
  if (chat) return chat;
  if (!value) return "<p><em>No description available.</em></p>";
  return value;
};

const cloneFeatToActor = async (templateItem, targetActor) => {
  const data = templateItem.toObject();
  delete data._id;
  foundry.utils.setProperty(data, "flags.world.cooking.isTemplate", false);
  data.effects = (data.effects ?? []).map((ef) => {
    const next = foundry.utils.deepClone(ef);
    delete next._id;
    next.disabled = false;
    next.transfer = true;
    next.origin = targetActor.uuid;
    return next;
  });
  const created = await targetActor.createEmbeddedDocuments("Item", [data]);
  return created?.[0] ?? null;
};

const removePriorMeals = async (targetActor) => {
  const stale = targetActor.items.filter((i) => {
    const cooking = foundry.utils.getProperty(i, "flags.world.cooking") ?? {};
    return Boolean(cooking.mealKey) && cooking.isTemplate !== true;
  });
  if (!stale.length) return;
  await targetActor.deleteEmbeddedDocuments("Item", stale.map((i) => i.id));
};

const rollAbilityCheck = async (caller, abilityId, { addProf = false, flavor = "" } = {}) => {
  const abl = caller.system?.abilities?.[abilityId];
  const mod = Number(abl?.mod ?? 0);
  const prof = Number(caller.system?.attributes?.prof ?? 0);
  const parts = ["1d20", String(mod)];
  if (addProf) parts.push(String(prof));
  const roll = await new Roll(parts.join(" + ")).evaluate();
  await roll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor: caller }),
    flavor: flavor || `${CONFIG.DND5E?.abilities?.[abilityId]?.label ?? abilityId} check`,
  });
  return Number(roll.total ?? 0);
};

/** @returns {{ index: number, d20: number, d6: number, total: number, formula: string }} */
const rollDailySkillIndex = async (caller) => {
  const roll = await new Roll("1d20 + 1d6 - 1").evaluate();
  const dice = roll.dice ?? [];
  const d20 = Number(dice[0]?.results?.[0]?.result ?? dice[0]?.total ?? 0);
  const d6 = Number(dice[1]?.results?.[0]?.result ?? dice[1]?.total ?? 0);
  const total = Number(roll.total ?? 1);
  const index = Math.min(25, Math.max(1, total));

  await roll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor: caller }),
    flavor: `Daily Skill table — d20(${d20}) + d6(${d6}) − 1 = ${total} → row #${index}`,
  });

  return {
    index,
    d20,
    d6,
    total,
    formula: "1d20 + 1d6 − 1",
  };
};

const formatDailyRollLine = (rollInfo, skillLabel) => {
  const { d20, d6, total, index } = rollInfo;
  return `d20(${d20}) + d6(${d6}) − 1 = <strong>${total}</strong> → row #${index}: ${esc(skillLabel)}`;
};

const pickNpcSteps = () => {
  const pool = STEP_LABELS.slice();
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, 3);
};

const runFelyneCookingFlow = async ({
  cookActor,
  caller,
  chargeForMeal = false,
  mealPriceGp = 2,
  handoffMacroId = "",
} = {}) => {
  if (!cookActor || !caller) {
    ui.notifications.warn("Felyne Cook: cook or hunter missing.");
    return false;
  }

  const meals = getMealTemplates(cookActor);
  if (!meals.length) {
    ui.notifications.error("Felyne Cook: no Rank 1 meals loaded on this NPC.");
    return false;
  }

  const price = Number(mealPriceGp) || 2;
  const charge = Boolean(chargeForMeal);
  const cookImg = cookActor.img || "icons/svg/cowled.svg";
  const greet = felynePick(FELYNE.greetMenu);
  const purseCp = currencyToCopper(caller.system?.currency ?? {});
  const purseGp = purseCp / 100;
  const canAfford = !charge || purseCp >= Math.round(price * 100);
  const orderLabel = charge
    ? (canAfford ? `Order meal — ${price} gp` : `Need ${price} gp`)
    : "Choose abilities";

  const mealCards = meals.map((m, idx) => {
    const dc = Number(foundry.utils.getProperty(m, "flags.world.cooking.dc") ?? 10);
    const img = m.img || cookImg;
    return `
      <button type="button" class="amw-fc-meal${idx === 0 ? " is-selected" : ""}" data-meal-id="${esc(m.id)}">
        <img src="${esc(img)}" alt="" />
        <span>
          <span class="amw-fc-meal-name">${esc(m.name)}</span>
          <span class="amw-fc-meal-sub">Rank 1 · 1 serving</span>
        </span>
        <span class="amw-fc-dc">DC ${esc(dc)}</span>
      </button>
    `;
  }).join("");

  const mealForm = await dialogForm(
    `${cookActor.name} — Camp Kitchen`,
    `${COOK_STYLES}
    <form class="amw-fc">
      <div class="amw-fc-banner">
        <img src="${esc(cookImg)}" alt="" />
        <div>
          <h3>${esc(cookActor.name)}</h3>
          <p><em>${esc(greet)}</em></p>
        </div>
      </div>
      <div class="amw-fc-meta">
        <span class="amw-fc-chip">Hunter <strong>${esc(caller.name)}</strong></span>
        <span class="amw-fc-chip">Range <strong>10 ft</strong></span>
        ${charge
    ? `<span class="amw-fc-chip">Rank 1 <strong>${esc(price)} gp</strong></span>`
    : `<span class="amw-fc-chip"><strong>Complimentary</strong></span>`}
      </div>
      ${charge ? `
      <div class="amw-fc-funds${canAfford ? "" : " is-broke"}">
        <span>Your pouch: <strong>${esc(formatGpAmount(purseGp))} gp</strong></span>
        <span>${canAfford
    ? `Ready to pay <strong>${esc(price)} gp</strong>`
    : `<strong>Not enough zenny</strong> — need ${esc(price)} gp`}</span>
      </div>` : ""}
      <div>
        <span class="amw-fc-section-label">Today's menu</span>
        <div class="amw-fc-meals" data-meal-list>${mealCards}</div>
        <input type="hidden" name="meal" value="${esc(meals[0].id)}" />
      </div>
      <div>
        <span class="amw-fc-section-label">Boon</span>
        <div class="amw-fc-boon meal-desc"></div>
      </div>
      <p class="amw-fc-hint">Tip: double-click a dish to confirm instantly.</p>
    </form>`,
    orderLabel,
    {
      width: 560,
      disableOk: charge && !canAfford,
      render: (html, ctx = {}) => {
        const root = html instanceof jQuery ? html[0] : html;
        const hidden = root.querySelector('input[name="meal"]');
        const desc = root.querySelector(".meal-desc");
        const buttons = [...root.querySelectorAll(".amw-fc-meal")];
        const okBtn = ctx.okBtn ?? root.closest(".app")?.querySelector?.('button[data-button="ok"]');

        const selectMeal = (id) => {
          if (hidden) hidden.value = id;
          for (const btn of buttons) {
            btn.classList.toggle("is-selected", btn.dataset.mealId === id);
          }
          const meal = meals.find((m) => m.id === id);
          if (desc) desc.innerHTML = meal ? getMealBoonHtml(meal) : "";
        };

        for (const btn of buttons) {
          btn.addEventListener("click", (ev) => {
            ev.preventDefault();
            selectMeal(btn.dataset.mealId);
          });
          btn.addEventListener("dblclick", (ev) => {
            ev.preventDefault();
            if (okBtn?.disabled) return;
            selectMeal(btn.dataset.mealId);
            okBtn?.click?.();
          });
        }
        selectMeal(hidden?.value || meals[0].id);
      },
    },
  );
  if (!mealForm) return false;

  const mealItem = meals.find((m) => m.id === mealForm.meal.value);
  if (!mealItem) {
    ui.notifications.warn("Felyne Cook: meal not found.");
    return false;
  }

  if (charge) {
    // Re-check funds at confirm time (pouch may have changed while the dialog was open).
    const spent = await trySpendGold(caller, price);
    if (!spent.ok) {
      const have = formatGpAmount(spent.haveGp);
      const line = felynePick(FELYNE.noGold(price, have));
      ui.notifications.warn(line);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: cookActor }),
        content: `
          <div class="dnd5e2">
            <h3>${esc(cookActor.name)}</h3>
            <p><em>${esc(line)}</em></p>
          </div>
        `,
      });
      return false;
    }

    const credited = await tryCreditCook(cookActor, price);
    const paidLine = felynePick(FELYNE.paid(price));
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: cookActor }),
      content: `
        <div class="dnd5e2">
          <h3>${esc(cookActor.name)} — Payment</h3>
          <p><em>${esc(paidLine)}</em></p>
          <p><strong>${esc(caller.name)}</strong> ordered <strong>${esc(mealItem.name)}</strong> for <strong>${price} gp</strong>${credited ? " (added to the cook's pouch)" : " (GM: credit the cook if desired)"}.</p>
        </div>
      `,
    });
  }

  const servings = 1;
  const baseDc = Number(foundry.utils.getProperty(mealItem, "flags.world.cooking.dc") ?? 10);
  const dc = baseDc;

  const abilityOptions = (selectedId) => ABILITIES.map((a) => (
    `<option value="${a.id}"${a.id === selectedId ? " selected" : ""}>${esc(a.label)}</option>`
  )).join("");

  const npcSteps = pickNpcSteps();
  const defaultAbilities = ["int", "wis", "dex"];

  const checkForm = await dialogForm(
    `${cookActor.name} — Cooking checks`,
    `${COOK_STYLES}
    <form class="amw-fc">
      <div class="amw-fc-banner">
        <img src="${esc(mealItem.img || cookImg)}" alt="" />
        <div>
          <h3>${esc(mealItem.name)}</h3>
          <p><em>${esc(felynePick(FELYNE.checks))}</em></p>
        </div>
      </div>
      <div class="amw-fc-meta">
        <span class="amw-fc-chip">DC <strong>${esc(dc)}</strong></span>
        <span class="amw-fc-chip">Servings <strong>${esc(servings)}</strong></span>
        <span class="amw-fc-chip">Use <strong>3 different</strong> abilities</span>
      </div>
      ${[1, 2, 3].map((n) => `
        <fieldset class="amw-fc-step">
          <legend>Check ${n}</legend>
          <p><strong>Step:</strong> ${esc(npcSteps[n - 1])}</p>
          <input type="hidden" name="step${n}" value="${esc(npcSteps[n - 1])}"/>
          <div class="form-group" style="margin:0;">
            <label>Ability</label>
            <select name="ability${n}">${abilityOptions(defaultAbilities[n - 1])}</select>
          </div>
        </fieldset>
      `).join("")}
      <div class="form-group" style="margin:0;">
        <label>Cook's utensils proficiency</label>
        <select name="profOn">
          <option value="">None</option>
          <option value="1">Add PB to check 1</option>
          <option value="2">Add PB to check 2</option>
          <option value="3">Add PB to check 3</option>
        </select>
      </div>
      <p class="amw-fc-hint">If proficient with cook's utensils, add your proficiency bonus to one check.</p>
    </form>`,
    "Roll checks",
    { width: 540 },
  );
  if (!checkForm) return false;

  const picks = [1, 2, 3].map((n) => ({
    step: String(checkForm[`step${n}`].value || npcSteps[n - 1]),
    ability: String(checkForm[`ability${n}`].value || "int"),
  }));

  if (new Set(picks.map((p) => p.ability)).size !== 3) {
    ui.notifications.warn("Felyne Cook: you must use three different ability scores, nya!");
    return false;
  }

  const profOn = Number(checkForm.profOn.value || 0);
  const totals = [];
  for (let i = 0; i < 3; i += 1) {
    const pick = picks[i];
    const addProf = profOn === i + 1;
    const ablLabel = CONFIG.DND5E?.abilities?.[pick.ability]?.label ?? pick.ability.toUpperCase();
    totals.push(await rollAbilityCheck(caller, pick.ability, {
      addProf,
      flavor: `Artisan Cooking — ${pick.step} (${ablLabel}${addProf ? " + proficiency" : ""})`,
    }));
  }

  const average = Math.floor(totals.reduce((a, b) => a + b, 0) / 3);
  const margin = average - dc;
  const success = average >= dc;

  let resultTitle = "Bland meal";
  let resultFlavor = felynePick(FELYNE.bland);
  let resultBody = "<p>The dish counts as a day's ration but grants <strong>no meal boon</strong>.</p>";
  const grantedNames = [];
  const canModifyCaller = caller.isOwner || game.user.isGM;
  /** @type {string[]} */
  const dailyDetailLines = [];

  if (success) {
    resultTitle = "Delicious success";
    resultFlavor = felynePick(FELYNE.delicious);
    if (!canModifyCaller) {
      resultBody = `<p><strong>${esc(caller.name)}</strong> cooked <strong>${esc(mealItem.name)}</strong>, but this client cannot grant items. Ask the GM to apply the meal feature.</p>`;
    } else {
      await removePriorMeals(caller);
      const mealGranted = await cloneFeatToActor(mealItem, caller);
      if (mealGranted) grantedNames.push(mealGranted.name);
      resultBody = `<p><strong>${esc(caller.name)}</strong> gains <strong>${esc(mealItem.name)}</strong>.</p>`;

      const dailyRolls = margin >= 8 ? 2 : margin >= 4 ? 1 : 0;
      if (dailyRolls > 0) {
        resultFlavor = `${resultFlavor} ${felynePick(FELYNE.daily)}`;
        const dailyMap = getDailyTemplates(cookActor);
        for (let i = 0; i < dailyRolls; i += 1) {
          const rollInfo = await rollDailySkillIndex(caller);
          const template = dailyMap.get(rollInfo.index);
          if (!template) {
            dailyDetailLines.push(formatDailyRollLine(rollInfo, `(missing template on cook)`));
            continue;
          }
          const already = caller.items.find((it) => {
            const key = foundry.utils.getProperty(it, "flags.world.cooking.skillKey");
            return key && key === foundry.utils.getProperty(template, "flags.world.cooking.skillKey");
          });
          if (already) {
            dailyDetailLines.push(formatDailyRollLine(rollInfo, `${template.name} (already known)`));
            continue;
          }
          const created = await cloneFeatToActor(template, caller);
          if (created) {
            grantedNames.push(created.name);
            dailyDetailLines.push(formatDailyRollLine(rollInfo, created.name));
          } else {
            dailyDetailLines.push(formatDailyRollLine(rollInfo, `${template.name} (grant failed)`));
          }
        }
        resultBody += `
          <p><strong>Daily Skill${dailyRolls > 1 ? "s" : ""}</strong> <em>(${felynePick(["lucky rollin', nya!", "extra helpin' from the pot!"])})</em>:</p>
          <ul>${dailyDetailLines.map((line) => `<li>${line}</li>`).join("")}</ul>
        `;
      }
    }
  } else if (margin <= -5) {
    resultTitle = "Ruined meal";
    resultFlavor = felynePick(FELYNE.ruined);
    resultBody = `<p>The meal does <strong>not</strong> count as a ration. ${esc(caller.name)} must succeed on a Constitution saving throw (DC ${dc}) or become poisoned for 1 hour.</p>`;
    if (typeof caller.rollSavingThrow === "function") {
      await caller.rollSavingThrow({ ability: "con", targetValue: dc });
    } else {
      await rollAbilityCheck(caller, "con", { flavor: `Constitution saving throw (DC ${dc}) vs ruined meal` });
    }
  }

  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: cookActor }),
    content: `
      <div class="dnd5e2">
        <h3>${esc(cookActor.name)} — Artisan Cooking (Rank 1)</h3>
        <p><em>${esc(resultFlavor)}</em></p>
        <p><strong>Cook:</strong> ${esc(caller.name)} &nbsp;|&nbsp; <strong>Meal:</strong> ${esc(mealItem.name)}${charge ? ` &nbsp;|&nbsp; <strong>Paid:</strong> ${price} gp` : ""}</p>
        <p><strong>Checks:</strong> ${totals.join(" / ")} &nbsp;|&nbsp; <strong>Average:</strong> ${average} vs DC ${dc} (${margin >= 0 ? "+" : ""}${margin})</p>
        <p><strong>${esc(resultTitle)}</strong></p>
        ${resultBody}
        ${grantedNames.length ? `<p><em>Granted:</em> ${grantedNames.map(esc).join(", ")}</p>` : ""}
      </div>
    `,
  });

  const macroId = typeof handoffMacroId === "string" ? handoffMacroId : "";
  if (macroId && game.user.isGM) {
    const handoff = game.macros.get(macroId);
    if (handoff) await handoff.delete().catch(() => null);
  }

  return true;
};

globalThis.__amellwindFelyneCook = globalThis.__amellwindFelyneCook || {};
globalThis.__amellwindFelyneCook.runCookingFlow = runFelyneCookingFlow;

// Legacy Ask / handoff macros: variables already in scope.
if (typeof cookActor !== "undefined" && cookActor && typeof caller !== "undefined" && caller) {
  await runFelyneCookingFlow({
    cookActor,
    caller,
    chargeForMeal: Boolean(typeof CHARGE_FOR_MEAL !== "undefined" && CHARGE_FOR_MEAL),
    mealPriceGp: Number(typeof MEAL_PRICE_GP !== "undefined" ? MEAL_PRICE_GP : 2) || 2,
    handoffMacroId: typeof HANDOFF_MACRO_ID === "string" ? HANDOFF_MACRO_ID : "",
  });
}


// Felyne Cook Sync engine - Amellwind (Foundry v12 / dnd5e 4.4)
// Arms token double-click interaction (Item Piles-style) and exposes cooking API.
// Cooking UI lives in felyne-cook-player-flow.fragment.js (concatenated by build
// before this file when shipping the module client script).
// Wrapped in an IIFE so it can be safely concatenated into Item Macros.

(() => {
const NS = "__amellwindFelyneCook";
const FLAG = "flags.world.cooking";
const RANGE_FT = 10;
const MEAL_PRICE_GP_DEFAULT = 2;

const measureDistanceFt = (tokenA, tokenB) => {
  if (!tokenA || !tokenB) return Infinity;
  if (typeof MidiQOL?.computeDistance === "function") {
    try {
      const d = Number(MidiQOL.computeDistance(tokenA, tokenB, { wallsBlock: false }));
      if (Number.isFinite(d)) return d;
    } catch (_err) {
      // fall through
    }
  }
  if (typeof canvas.grid?.measurePath === "function") {
    const path = canvas.grid.measurePath([tokenA.center, tokenB.center]);
    const d = Number(path?.distance ?? path?.spaces);
    if (Number.isFinite(d)) return d;
  }
  const d = Number(canvas.grid.measureDistance(tokenA.center, tokenB.center, { gridSpaces: true }));
  return Number.isFinite(d) ? d : Infinity;
};

const isPcActor = (actorDoc) => {
  if (!actorDoc) return false;
  if (actorDoc.type === "character") return true;
  return game.users.some((u) => !u.isGM && actorDoc.testUserPermission?.(u, "OWNER"));
};

const isCookActor = (actorDoc) => {
  if (!actorDoc) return false;
  if (foundry.utils.getProperty(actorDoc, `${FLAG}.cookNpc`) === true) return true;
  if (foundry.utils.getProperty(actorDoc, `${FLAG}.isCookToken`) === true) return true;
  // LIMITED clients may not see items/flags — name fallback for the stock NPC.
  if (/^felyne cook$/i.test(String(actorDoc.name ?? "").trim())) return true;
  return actorDoc.items?.some?.(
    (i) => foundry.utils.getProperty(i, `${FLAG}.isKitchenAuraItem`) === true
      || foundry.utils.getProperty(i, `${FLAG}.requestMeal`) === true
      || foundry.utils.getProperty(i, `${FLAG}.playerRequestTemplate`) === true,
  ) === true;
};

const defaultCookCfg = () => ({
  cookNpc: true,
  isCookToken: true,
  enabled: true,
  interactionDistance: RANGE_FT,
  mealPriceGp: MEAL_PRICE_GP_DEFAULT,
});

const readCookFlag = (doc) => {
  if (!doc) return null;
  const f = foundry.utils.getProperty(doc, FLAG);
  if (!f || typeof f !== "object") return null;
  if (f.cookNpc === true || f.isCookToken === true) {
    return {
      cookNpc: true,
      isCookToken: true,
      enabled: f.enabled !== false,
      interactionDistance: Number.isFinite(Number(f.kitchenAuraFt ?? f.interactionDistance))
        ? Number(f.kitchenAuraFt ?? f.interactionDistance)
        : RANGE_FT,
      mealPriceGp: Number.isFinite(Number(f.mealPriceGp)) ? Number(f.mealPriceGp) : MEAL_PRICE_GP_DEFAULT,
    };
  }
  return null;
};

const resolveCookContext = (tokenPlaceable) => {
  const tokenDoc = tokenPlaceable?.document ?? null;
  const actorDoc = tokenPlaceable?.actor ?? null;
  const tokenName = String(tokenDoc?.name ?? tokenPlaceable?.name ?? "").trim();
  const cfg =
    readCookFlag(tokenDoc)
    ?? readCookFlag(actorDoc)
    ?? (isCookActor(actorDoc)
      ? {
          ...defaultCookCfg(),
          interactionDistance: Number(foundry.utils.getProperty(actorDoc, `${FLAG}.kitchenAuraFt`)) || RANGE_FT,
        }
      : null)
    // Player clients often cannot read LIMITED NPC flags/items — match token name.
    ?? (/^felyne cook$/i.test(tokenName) ? defaultCookCfg() : null);
  return { tokenDoc, actorDoc, cfg };
};

const isCookToken = (tokenPlaceable) => Boolean(resolveCookContext(tokenPlaceable).cfg?.enabled);

const limitedOwnershipLevel = () => CONST.DOCUMENT_OWNERSHIP_LEVELS?.OBSERVER
  ?? CONST.DOCUMENT_OWNERSHIP_LEVELS?.LIMITED
  ?? 2;

/**
 * Publish a player-readable cook marker on Actor + TokenDocuments and raise
 * default ownership to LIMITED so double-click works without OWNER.
 */
const syncPublicCookMarkers = async (cookActor, cfg = null) => {
  if (!cookActor || !(game.user.isGM || cookActor.isOwner)) return;
  const marker = {
    cookNpc: true,
    isCookToken: true,
    enabled: cfg?.enabled !== false,
    kitchenAuraFt: cfg?.interactionDistance ?? RANGE_FT,
    interactionDistance: cfg?.interactionDistance ?? RANGE_FT,
    mealPriceGp: cfg?.mealPriceGp ?? MEAL_PRICE_GP_DEFAULT,
  };

  const patch = { [`${FLAG}`]: marker };
  try {
    const limited = limitedOwnershipLevel();
    if ((cookActor.ownership?.default ?? 0) < limited) {
      patch.ownership = { ...(cookActor.ownership ?? {}), default: limited };
    }
    await cookActor.update(patch);
  } catch (_err) {
    // non-fatal
  }

  for (const tok of cookActor.getActiveTokens?.(false) ?? []) {
    try {
      await tok.document.update({ [FLAG]: marker });
    } catch (_err) {
      // optional
    }
  }
};

const publishAllCookMarkers = async () => {
  if (!game.user.isGM) return 0;
  let count = 0;
  for (const actor of game.actors ?? []) {
    if (!isCookActor(actor)) continue;
    const cfg = readCookFlag(actor) ?? {
      enabled: true,
      interactionDistance: Number(foundry.utils.getProperty(actor, `${FLAG}.kitchenAuraFt`)) || RANGE_FT,
      mealPriceGp: MEAL_PRICE_GP_DEFAULT,
    };
    const limited = limitedOwnershipLevel();
    const needsOwnership = (actor.ownership?.default ?? 0) < limited;
    const needsActorFlag = !readCookFlag(actor)?.isCookToken;
    let needsTokenFlag = false;
    for (const tok of actor.getActiveTokens?.(false) ?? []) {
      if (!readCookFlag(tok.document)?.isCookToken) {
        needsTokenFlag = true;
        break;
      }
    }
    if (needsOwnership || needsActorFlag || needsTokenFlag) {
      await syncPublicCookMarkers(actor, cfg);
      count += 1;
    }
  }
  return count;
};

const resolveHunterActor = (cookActor = null, cookToken = null) => {
  const cookId = cookActor?.id ?? null;

  const ownedTokens = (canvas.tokens?.placeables ?? []).filter(
    (t) => t?.actor && isPcActor(t.actor) && t.actor.isOwner && t.actor.id !== cookId,
  );

  if (ownedTokens.length >= 1) {
    if (game.user.character) {
      const assigned = ownedTokens.find((t) => t.actor.id === game.user.character.id);
      if (assigned) return assigned.actor;
    }
    if (ownedTokens.length === 1 || !cookToken) {
      return ownedTokens[0].actor;
    }
    let best = ownedTokens[0];
    let bestDist = measureDistanceFt(best, cookToken);
    for (let i = 1; i < ownedTokens.length; i += 1) {
      const t = ownedTokens[i];
      const d = measureDistanceFt(t, cookToken);
      if (d < bestDist) {
        best = t;
        bestDist = d;
      }
    }
    return best.actor;
  }

  if (game.user.character && isPcActor(game.user.character) && game.user.character.id !== cookId) {
    return game.user.character;
  }

  const controlled = (canvas.tokens?.controlled ?? [])
    .map((t) => t.actor)
    .filter((a) => a && isPcActor(a) && a.id !== cookId);
  if (controlled.length >= 1) {
    return controlled.find((a) => a.isOwner) ?? (game.user.isGM ? controlled[0] : null);
  }

  return null;
};

const openCookMenu = async ({ cookToken, hunterActor, chargeForMeal = true } = {}) => {
  const ctx = cookToken ? resolveCookContext(cookToken) : null;
  let cookActor = cookToken?.actor ?? ctx?.actorDoc ?? null;
  const cfg = ctx?.cfg;
  if (!cfg?.enabled) {
    ui.notifications.warn("Felyne Cook: this token is not a camp kitchen.");
    return false;
  }
  if (!cookActor && cookToken?.document?.actorId) {
    cookActor = game.actors.get(cookToken.document.actorId) ?? null;
  }
  if (!cookActor && cookToken?.document?.actorUuid) {
    try {
      cookActor = await fromUuid(cookToken.document.actorUuid);
    } catch (_err) {
      cookActor = null;
    }
  }
  if (!cookActor) {
    ui.notifications.warn(
      "Felyne Cook: cannot read the cook actor. GM: set default ownership to Observer and re-place the token (or run Kitchen Sync).",
    );
    return false;
  }

  const hunter = hunterActor ?? resolveHunterActor(cookActor, cookToken);
  if (!hunter) {
    ui.notifications.warn(
      "Felyne Cook: place your character token on the scene within 10 ft (or assign a User Character), then double-click the cook again.",
    );
    return false;
  }
  if (!hunter.isOwner && !game.user.isGM) {
    ui.notifications.warn("Felyne Cook: you do not own that character.");
    return false;
  }

  const hunterToken =
    (canvas.tokens?.placeables ?? []).find((t) => t.actor?.id === hunter.id && t.actor?.isOwner)
    ?? hunter.getActiveTokens?.(true)?.[0]
    ?? null;

  const maxDist = cfg.interactionDistance ?? RANGE_FT;
  if (cookToken && hunterToken && maxDist > 0) {
    const dist = measureDistanceFt(hunterToken, cookToken);
    if (dist > maxDist + 1e-6) {
      ui.notifications.warn(
        `Felyne Cook: too far away (${Math.round(dist * 10) / 10} ft; need ≤ ${maxDist} ft), nya!`,
      );
      return false;
    }
  }

  const run = globalThis[NS]?.runCookingFlow;
  if (typeof run !== "function") {
    ui.notifications.error(
      "Felyne Cook: cooking UI missing. Enable the Amellwind module or re-import the cook actor.",
    );
    return false;
  }

  return run({
    cookActor,
    caller: hunter,
    chargeForMeal,
    mealPriceGp: cfg.mealPriceGp ?? MEAL_PRICE_GP_DEFAULT,
    handoffMacroId: "",
  });
};

const applyCookClickPermissions = (tokenPlaceable) => {
  const mim = tokenPlaceable?.mouseInteractionManager;
  if (!mim?.permissions || !isCookToken(tokenPlaceable)) return;
  mim.permissions.clickLeft = () => true;
  mim.permissions.clickLeft2 = () => true;
};

const refreshAllCookClickPermissions = () => {
  for (const tok of canvas.tokens?.placeables ?? []) {
    applyCookClickPermissions(tok);
  }
};

const handleCookTokenInteract = async (tokenPlaceable, event) => {
  const { actorDoc, cfg } = resolveCookContext(tokenPlaceable);
  if (!cfg?.enabled) return false;

  // Alt+double-click → normal actor sheet for GM only.
  if (event?.altKey) return false;

  // GM Shift+double-click always opens the cook sheet (meals / templates).
  if (game.user.isGM && event?.shiftKey) {
    actorDoc?.sheet?.render?.(true);
    return true;
  }

  const hunter = resolveHunterActor(actorDoc, tokenPlaceable);
  if (!hunter && game.user.isGM) {
    actorDoc?.sheet?.render?.(true);
    return true;
  }

  await openCookMenu({
    cookToken: tokenPlaceable,
    hunterActor: hunter,
    chargeForMeal: true,
  });
  return true;
};

const ensureFelyneCookHooks = () => {
  globalThis[NS] = globalThis[NS] || {};
  Object.assign(globalThis[NS], {
    ensureFelyneCookHooks,
    openCookMenu,
    syncPublicCookMarkers,
    publishAllCookMarkers,
    resolveHunterActor,
    resolveCookContext,
    isCookActor,
    isCookToken,
    measureDistanceFt,
    RANGE_FT,
  });

  const wrapClick = () => {
    if (globalThis[NS].clickWrapped) return true;
    const proto = CONFIG.Token?.objectClass?.prototype;
    if (!proto || typeof proto._onClickLeft2 !== "function") return false;

    // Always chain via prototype patch. Resource Node already claims
    // libWrapper for this package + _onClickLeft2; a second register is a no-op/throw.
    const original = proto._onClickLeft2;
    proto._onClickLeft2 = function felyneCookOnClickLeft2(event) {
      try {
        if (isCookToken(this)) {
          if (event?.altKey && game.user.isGM) {
            return original.call(this, event);
          }
          event?.preventDefault?.();
          event?.stopPropagation?.();
          Promise.resolve(handleCookTokenInteract(this, event)).catch((err) => {
            console.error("Felyne Cook click handler error", err);
            ui.notifications?.error?.(`Felyne Cook: ${err?.message || err}`);
          });
          return false;
        }
      } catch (err) {
        console.error("Felyne Cook click handler error", err);
        ui.notifications?.error?.(`Felyne Cook: ${err?.message || err}`);
      }
      return original.call(this, event);
    };

    globalThis[NS].clickWrapped = true;
    console.log("Amellwind Felyne Cook | _onClickLeft2 wrapped");
    return true;
  };

  const armInteraction = () => {
    const wrapped = wrapClick();
    refreshAllCookClickPermissions();
    return wrapped;
  };

  if (!globalThis[NS].hooksReady) {
    globalThis[NS].hooksReady = true;

    Hooks.on("canvasReady", () => {
      armInteraction();
    });
    Hooks.on("refreshToken", (token) => {
      applyCookClickPermissions(token);
    });
    Hooks.on("createToken", (tokenDoc) => {
      const placeable = tokenDoc?.object;
      if (placeable) applyCookClickPermissions(placeable);
    });

    Hooks.on("renderActorSheet", (app) => {
      try {
        const actorDoc = app.actor;
        if (!isCookActor(actorDoc) && !readCookFlag(actorDoc)) return;
        // Opening the cook sheet also (re)arms interaction — useful after JSON import.
        armInteraction();
        if (game.user.isGM) {
          Promise.resolve(syncPublicCookMarkers(actorDoc, readCookFlag(actorDoc))).catch(() => null);
          return;
        }
        // Players opening the cook sheet are redirected to the kitchen menu.
        setTimeout(() => {
          app.close?.();
          const tok = actorDoc.getActiveTokens?.(true)?.[0] ?? null;
          openCookMenu({ cookToken: tok, chargeForMeal: true });
        }, 0);
      } catch (_err) {
        // optional
      }
    });
  }

  armInteraction();
  // Token class may not exist yet during early boot — retry shortly.
  if (!globalThis[NS].clickWrapped) {
    Hooks.once("ready", () => {
      armInteraction();
      if (canvas?.ready) armInteraction();
    });
    setTimeout(() => armInteraction(), 250);
    setTimeout(() => armInteraction(), 1500);
  }

  return globalThis[NS];
};


  ensureFelyneCookHooks();
})();


// Felyne Cook — Kitchen Aura grant/revoke + distance sync (Foundry runtime)
// Grants "Ask for a Meal (Rank 1)" to characters within 10 ft of a cookNpc NPC.
// Wrapped in an IIFE so it can be concatenated with the token sync engine safely.

(() => {

  const RANGE_FT_AURA = 10;

  const measureDistanceFtAura = (tokenA, tokenB) => {
    if (!tokenA || !tokenB) return Infinity;
    if (typeof MidiQOL?.computeDistance === "function") {
      const d = Number(MidiQOL.computeDistance(tokenA, tokenB, { wallsBlock: false }));
      if (Number.isFinite(d)) return d;
    }
    if (typeof canvas.grid?.measurePath === "function") {
      const path = canvas.grid.measurePath([tokenA.center, tokenB.center]);
      const d = Number(path?.distance ?? path?.spaces);
      if (Number.isFinite(d)) return d;
    }
    const d = Number(canvas.grid.measureDistance(tokenA.center, tokenB.center, { gridSpaces: true }));
    return Number.isFinite(d) ? d : Infinity;
  };

  const isCookActor = (actorDoc) => {
    if (!actorDoc) return false;
    if (foundry.utils.getProperty(actorDoc, "flags.world.cooking.cookNpc") === true) return true;
    return actorDoc.items?.some?.(
      (i) => foundry.utils.getProperty(i, "flags.world.cooking.isKitchenAuraItem") === true
        || foundry.utils.getProperty(i, "flags.world.cooking.playerRequestTemplate") === true,
    ) === true;
  };

  const resolveCookFromEffect = async (effect) => {
    if (!effect?.origin) return null;
    try {
      const origin = await fromUuid(effect.origin);
      if (!origin) return null;
      if (origin.documentName === "Actor") return origin;
      if (origin.documentName === "Item") return origin.actor ?? origin.parent ?? null;
      if (origin.documentName === "ActiveEffect") {
        const parent = origin.parent;
        if (!parent) return null;
        if (parent.documentName === "Actor") return parent;
        if (parent.documentName === "Item") return parent.actor ?? parent.parent ?? null;
      }
    } catch (_err) {
      return null;
    }
    return null;
  };

  const grantAskFeature = async (targetActor, cookActor) => {
    if (!targetActor || targetActor.type !== "character" || !cookActor) return false;
    if (targetActor.items.some((i) => foundry.utils.getProperty(i, "flags.world.cooking.playerRequest") === true)) {
      // Keep cook uuid fresh on existing feature.
      const existing = targetActor.items.find(
        (i) => foundry.utils.getProperty(i, "flags.world.cooking.playerRequest") === true,
      );
      if (existing && foundry.utils.getProperty(existing, "flags.world.cooking.cookActorUuid") !== cookActor.uuid) {
        await existing.update({ "flags.world.cooking.cookActorUuid": cookActor.uuid });
      }
      return false;
    }

    const template = cookActor.items.find(
      (i) => foundry.utils.getProperty(i, "flags.world.cooking.playerRequestTemplate") === true,
    );
    if (!template) {
      console.warn("Felyne Cook: Ask feature template missing on cook actor.");
      ui.notifications?.warn?.("Felyne Cook: Ask feature template missing on cook actor.");
      return false;
    }

    const data = template.toObject();
    delete data._id;
    data.name = "Ask for a Meal (Rank 1)";
    data.effects = [];
    foundry.utils.setProperty(data, "flags.world.cooking.playerRequestTemplate", false);
    foundry.utils.setProperty(data, "flags.world.cooking.playerRequest", true);
    foundry.utils.setProperty(data, "flags.world.cooking.fromAura", true);
    foundry.utils.setProperty(data, "flags.world.cooking.cookActorUuid", cookActor.uuid);
    foundry.utils.setProperty(data, "system.identifier", "ask-for-a-meal-rank-1");
    await targetActor.createEmbeddedDocuments("Item", [data]);
    return true;
  };

  const revokeAskFeature = async (targetActor) => {
    if (!targetActor) return false;
    const stale = targetActor.items.filter(
      (i) => foundry.utils.getProperty(i, "flags.world.cooking.fromAura") === true
        && foundry.utils.getProperty(i, "flags.world.cooking.playerRequest") === true,
    );
    if (!stale.length) return false;
    await targetActor.deleteEmbeddedDocuments("Item", stale.map((i) => i.id));
    return true;
  };

  const syncKitchenFeatures = async ({ notify = false } = {}) => {
    if (!game.user.isGM) return;
    if (game.users.activeGM && game.users.activeGM.id !== game.user.id) return;
    if (!canvas?.ready) return;

    const cookTokens = (canvas.tokens?.placeables ?? []).filter((t) => isCookActor(t.actor));
    const hunterTokens = (canvas.tokens?.placeables ?? []).filter((t) => t.actor?.type === "character");

    let granted = 0;
    let revoked = 0;

    for (const hunterTok of hunterTokens) {
      const hunter = hunterTok.actor;
      if (!hunter) continue;

      let nearest = null;
      let nearestDist = Infinity;
      for (const cookTok of cookTokens) {
        const dist = measureDistanceFtAura(hunterTok, cookTok);
        if (dist < nearestDist) {
          nearestDist = dist;
          nearest = cookTok.actor;
        }
      }

      const inRange = Boolean(nearest) && nearestDist <= RANGE_FT_AURA + 1e-6;
      const hasAsk = hunter.items.some(
        (i) => foundry.utils.getProperty(i, "flags.world.cooking.playerRequest") === true,
      );

      if (inRange && !hasAsk) {
        if (await grantAskFeature(hunter, nearest)) granted += 1;
      } else if (!inRange && hasAsk) {
        if (await revokeAskFeature(hunter)) revoked += 1;
      } else if (inRange && hasAsk && nearest) {
        await grantAskFeature(hunter, nearest); // refresh cook uuid if needed
      }
    }

    if (notify) {
      ui.notifications.info(`Felyne Cook kitchen sync: +${granted} granted, −${revoked} removed.`);
    }

    // Refresh Active Auras visuals if available.
    try {
      const sceneId = canvas.scene?.id;
      if (game.modules.get("ActiveAuras")?.active && sceneId && globalThis.ActiveAuras?.CollateAuras) {
        await ActiveAuras.CollateAuras(sceneId, true, true, "felyne-cook-kitchen-sync");
      }
    } catch (_err) {
      // optional
    }
  };

  globalThis.__amellwindFelyneCookAura = globalThis.__amellwindFelyneCookAura || {};
  Object.assign(globalThis.__amellwindFelyneCookAura, {
    grantAskFeature,
    revokeAskFeature,
    resolveCookFromEffect,
    syncKitchenFeatures,
    RANGE_FT_AURA,
  });

  if (!globalThis.__amellwindFelyneCookAura.hooksReady) {
    globalThis.__amellwindFelyneCookAura.hooksReady = true;

    let syncTimer = null;
    const queueSync = () => {
      if (syncTimer) clearTimeout(syncTimer);
      syncTimer = setTimeout(() => {
        syncKitchenFeatures({ notify: false });
      }, 250);
    };

    Hooks.on("createActiveEffect", async (effect) => {
      if (!game.user.isGM) return;
      if (game.users.activeGM && game.users.activeGM.id !== game.user.id) return;
      if (foundry.utils.getProperty(effect, "flags.world.cooking.isKitchenAura") !== true) return;

      const targetActor = effect.parent;
      if (!targetActor || targetActor.documentName !== "Actor" || targetActor.type !== "character") return;

      const cookActor = (await resolveCookFromEffect(effect))
        || (canvas.tokens?.placeables ?? []).find((t) => isCookActor(t.actor))?.actor;
      if (!cookActor || cookActor.id === targetActor.id) return;
      await grantAskFeature(targetActor, cookActor);
    });

    Hooks.on("deleteActiveEffect", async (effect) => {
      if (!game.user.isGM) return;
      if (game.users.activeGM && game.users.activeGM.id !== game.user.id) return;
      if (foundry.utils.getProperty(effect, "flags.world.cooking.isKitchenAura") !== true) return;
      queueSync();
    });

    Hooks.on("canvasReady", () => queueSync());
    Hooks.on("createToken", () => queueSync());
    Hooks.on("deleteToken", () => queueSync());
    Hooks.on("updateToken", (_doc, changes) => {
      if ("x" in changes || "y" in changes || "elevation" in changes || "actorId" in changes) {
        queueSync();
      }
    });

    // If this fragment loads mid-session (macro use), sync immediately.
    if (canvas?.ready) queueSync();
  }

})();


try {
  globalThis.__amellwindFelyneCook?.ensureFelyneCookHooks?.();
} catch (err) {
  console.error("Felyne Cook | failed to arm token hooks", err);
}

if (game.user.isGM) {
  try {
    const n = await globalThis.__amellwindFelyneCook?.publishAllCookMarkers?.();
    if (n > 0) {
      console.log(`Felyne Cook | published markers for ${n} cook actor(s)`);
    }
  } catch (err) {
    console.error("Felyne Cook | marker publish failed", err);
  }

  try {
    await globalThis.__amellwindFelyneCookAura?.syncKitchenFeatures?.({ notify: true });
  } catch (err) {
    console.error("Felyne Cook | kitchen aura sync failed", err);
    ui.notifications.warn("Felyne Cook: aura sync failed (see console).");
  }
} else {
  ui.notifications.info("Felyne Cook: kitchen hooks armed on this client.");
}
